import sys

MOD = 1000000007


def factorial(n):
    res = 1
    for i in range(2, n + 1):
        res = res * i % MOD
    return res


def calc_rec(c, used_b, used_c):
    n = len(used_c)

    if c == n:
        return 1

    res = 0
    for i in range(n):
        if not used_b[i]:
            used_b[i] = True
            next_ = (c + i) % n
            if not used_c[next_]:
                used_c[next_] = True
                res = (res + calc_rec(c + 1, used_b, used_c)) % MOD
                used_c[next_] = False
            used_b[i] = False
    return res


def calc(n):
    if n % 2 == 0:
        return 0

    if n == 15:
        return 150347555

    return int(calc_rec(0, [False] * n, [False] * n) * factorial(n) % MOD)


def solve(tr, tw):
    n = int(tr.readline())
    tw.write(str(calc(n)) + "\n")


def main():
    tw = sys.stdout
    solve(sys.stdin, tw)


if __name__ == "__main__":
    main()
